// src/utils/phoneUtils.ts
/**
* Normalizes phone numbers from Venezuela format (e.g. "424-2510098", "0424 2510098")
* to international E.164 without plus: "584242510098"
*/
function formatVenezuelaPhone(raw) {
	if (!raw) return "";
	const digits = raw.replace(/\D/g, "");
	if (!digits) return "";
	if (digits.startsWith("58") && digits.length >= 12) return digits;
	if (digits.startsWith("0") && digits.length === 11) return "58" + digits.substring(1);
	if (digits.length === 10) return "58" + digits;
	return digits;
}
function getWhatsAppUrl(phone, contactName) {
	const normalized = formatVenezuelaPhone(phone);
	if (!normalized) return "#";
	return `https://wa.me/${normalized}?text=${contactName ? encodeURIComponent(`Hola ${contactName}, te contacto desde la Agenda de Contactos Farma.`) : encodeURIComponent("Hola, te contacto desde la Agenda de Contactos Farma.")}`;
}
function getTelUrl(phone) {
	const normalized = formatVenezuelaPhone(phone);
	if (!normalized) return "#";
	return `tel:+${normalized}`;
}
function downloadVCard(contact, isRep) {
	const fullName = contact.nombre;
	const org = "La Santé";
	const role = isRep ? "Representante Sales Farma" : contact.cargo || "Gerente de Distrito";
	const phone = contact.telefono;
	const email = contact.correo;
	const normPhone = formatVenezuelaPhone(phone);
	let note = "";
	if (isRep) {
		const rep = contact;
		note = `Región: ${rep.region} | Unidad: ${getMappedUnit(rep.unidadNegocio)} | Gerente: ${rep.gerenteDistrito} | Cédula: ${rep.cedula} | Sector: ${rep.codigoSector}`;
	} else {
		const gd = contact;
		note = `Cargo: ${gd.cargo} | Región: ${gd.region} | Supervisor: ${gd.supervisor} | Cédula: ${gd.cedula}`;
	}
	const vcard = [
		"BEGIN:VCARD",
		"VERSION:3.0",
		`FN:${fullName}`,
		`ORG:${org}`,
		`TITLE:${role}`,
		phone ? `TEL;TYPE=CELL,VOICE:+${normPhone}` : "",
		email ? `EMAIL;TYPE=WORK,INTERNET:${email}` : "",
		contact.ciudad ? `ADR;TYPE=WORK:;;${contact.ciudad};${contact.estado || ""};;;Venezuela` : "ADR;TYPE=WORK:;;;;;;Venezuela",
		`NOTE:${note}`,
		"END:VCARD"
	].filter(Boolean).join("\r\n");
	const blob = new Blob([vcard], { type: "text/vcard;charset=utf-8" });
	const url = URL.createObjectURL(blob);
	const link = document.createElement("a");
	link.href = url;
	link.download = `${fullName.toLowerCase().replace(/[^a-z0-9]/g, "_")}.vcf`;
	document.body.appendChild(link);
	link.click();
	document.body.removeChild(link);
	URL.revokeObjectURL(url);
}
