	if (clean === "CAPITAL OESTE" || clean === "CAPITAL-OESTE" || clean.includes("CAPITAL") && clean.includes("OESTE")) return "3 - CAPITAL OESTE";
	if (clean === "ANDES" || clean.includes("ANDE")) return "1 - ANDES";
