async function getSpreadsheetDetails(spreadsheetId) {
	const token = await getAccessToken();
	if (!token) throw new Error("Debes iniciar sesión con Google para acceder a las hojas.");
	const res = await fetch(`https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}`, { headers: { Authorization: `Bearer ${token}` } });
	if (!res.ok) {
		const err = await res.text();
		throw new Error(`Error al leer la hoja de cálculo (${res.status}): ${err}`);
	}
	const data = await res.json();
	const sheets = (data.sheets || []).map((s) => s.properties?.title);
	return {
		title: data.properties?.title || "Hoja de Google Sheets",
		sheets
	};
}
